/* Local SVG UI icons. Only interface-owned icon slots and controls are normalized. */
(()=>{
'use strict';
const paths={"sun":"<circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2\"/>","close":"<path d=\"m6 6 12 12M6 18 18 6\"/>","plus":"<path d=\"M12 5v14M5 12h14\"/>","send":"<path d=\"m5 19 14-14M5 5h14v14\"/>","arrow":"<path d=\"M4 12h16m-6-6 6 6-6 6\"/>","coin":"<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9m3-10v12\"/>","heart":"<path d=\"M20 5c-3-3-7-1-8 1-2-3-6-3-8-1-5 5 2 10 8 15 6-5 13-10 8-15Z\"/>","food":"<path d=\"M3 11h18a9 9 0 0 1-18 0Zm4 10h10M8 3v4m4-5v5m4-4v4\"/>","drink":"<path d=\"M7 8h10l-1 13H8L7 8Zm6 0 2-6h4M5 8h14\"/>","drop":"<path d=\"M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Zm-3 13a3 3 0 0 0 3 3\"/>","toy":"<rect x=\"3\" y=\"7\" width=\"18\" height=\"13\" rx=\"5\"/><path d=\"M7 11v6m-3-3h6m6-2h.01M19 16h.01M9 7l1-4h4l1 4\"/>","snack":"<path d=\"m5 4 4 1 3-2 3 2 4-1v16l-4-1-3 2-3-2-4 1V4Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>","gift":"<rect x=\"3\" y=\"8\" width=\"18\" height=\"4\" rx=\"1\"/><path d=\"M5 12v9h14v-9M12 8v13m0-13C5 9 4 2 8 3c3 0 4 5 4 5Zm0 0c7 1 8-6 4-5-3 0-4 5-4 5Z\"/>","star":"<path d=\"m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1 3-6Z\"/>","video":"<rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"3\"/><path d=\"m10 9 5 3-5 3V9Z\"/>","speaker":"<path d=\"M11 4 5 9H2v6h3l6 5V4Zm4 4c3 2 3 6 0 8m3-11c5 4 5 10 0 14\"/>","pause":"<path d=\"M8 5v14M16 5v14\"/>","check":"<path d=\"m4 12 5 5L20 6\"/>","refresh":"<path d=\"M20 7a9 9 0 1 0 1 8M20 2v6h-6\"/>","menu":"<circle cx=\"5\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"19\" cy=\"12\" r=\"1\"/>","attach":"<path d=\"m8 12 6-6a3 3 0 0 1 4 4L9 19a5 5 0 0 1-7-7L12 2\"/>","user":"<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 22v-3a8 8 0 0 1 16 0v3\"/>","info":"<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v6m0-10h.01\"/>"};
const glyphs={'✳':'user','✦':'star','☼':'sun','☀':'sun','♫':'speaker','×':'close','✕':'close','✖':'close','＋':'plus','↗':'send','↥':'attach','→':'arrow','←':'arrow','•••':'menu','⋯':'menu','💙':'heart','❤️':'heart','❤':'heart','🍚':'food','🍎':'food','🍞':'food','🍜':'food','🥗':'food','💧':'drop','🥤':'drink','☕':'drink','🧃':'drink','🧸':'toy','🎮':'toy','🎁':'gift','📦':'gift','🍪':'snack','🍫':'snack','🌟':'star','✨':'star','⭐':'star','🪙':'coin','🎞':'video','🎬':'video','▶':'video','⏸':'pause','🔊':'speaker','🔈':'speaker','📎':'attach','✓':'check','✅':'check','↻':'refresh','ℹ':'info'};
function markup(name){const safe=Object.hasOwn(paths,name)?name:'gift';return '<svg class="uoya-icon" data-icon="'+safe+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+paths[safe]+'</svg>';}
function element(name){const template=document.createElement('template');template.innerHTML=markup(name);return template.content.firstElementChild;}
function product(item){const name=(Object.hasOwn(paths,item?.emoji)?item.emoji:glyphs[item?.emoji])||({food:'food',drink:'drink',snack:'snack',toy:'toy'})[item?.category]||'gift';return markup(name);}
globalThis.UoyaIcons=Object.freeze({markup,element,product});
const slots='.blue-icon,.agent-icon,.auth-symbol,.mini-ai-icon,.msg-avatar.ai,.latest-message-avatar,.product-emoji,.inventory-icon,.stat-icon,.coin-medallion,.brandIcon,.ai-avatar,.tip-icon,.account-arrow,.header-channel-icon,.mood-chip,.product-price,.ai-wallet,summary';
const exclude='svg,script,style,textarea,input,option,pre,code,.msg-content,.latest-message-content,[contenteditable=true]';
const pattern=new RegExp(Object.keys(glyphs).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^$\{\}()|[\]\\]/g,'\\$&')).join('|'),'gu');
function convert(el){
 if(!el?.matches||el.closest(exclude))return;
 if(el.matches('button')&&!el.hasAttribute('aria-label')){const label=({close:'关闭',plus:'添加',send:'发送',arrow:'继续',attach:'上传文件',menu:'更多',refresh:'刷新'})[glyphs[el.textContent.trim()]];if(label)el.setAttribute('aria-label',label);}
 if(el.matches('.header-channel-icon')&&el.textContent.trim()==='#'){el.replaceChildren(element('menu'));return;}
 const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){if(node.parentElement.closest(exclude))continue;const text=node.textContent;pattern.lastIndex=0;if(!pattern.test(text))continue;pattern.lastIndex=0;const fragment=document.createDocumentFragment();let start=0;for(const match of text.matchAll(pattern)){fragment.append(document.createTextNode(text.slice(start,match.index)),element(glyphs[match[0]]));start=match.index+match[0].length;}fragment.append(document.createTextNode(text.slice(start)));node.replaceWith(fragment);}
}
function scan(root){if(root.nodeType===3){const slot=root.parentElement?.closest(slots+',button');if(slot)convert(slot);return;}if(root.nodeType!==1&&root.nodeType!==9)return;if(root.nodeType===1){if(root.closest(exclude))return;if(root.matches(slots+',button'))convert(root);}root.querySelectorAll(slots+',button').forEach(convert);}
function init(){scan(document);new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')scan(record.target);else{for(const node of record.addedNodes)scan(node);}}}).observe(document.body,{childList:true,subtree:true,characterData:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
